const clone=value=>JSON.parse(JSON.stringify(value));
function filterLocal(events,filters={}){
  return events.filter(e=>Object.entries(filters).every(([key,value])=>{
    if(value==null||value==='')return true;
    if(key==='q')return JSON.stringify(e).toLocaleLowerCase().includes(String(value).toLocaleLowerCase());
    if(key==='start')return e.timestamp&&Date.parse(e.timestamp)>=Date.parse(value);
    if(key==='end')return e.timestamp&&Date.parse(e.timestamp)<=Date.parse(value);
    if(key==='rule_id')return (e.detection_rules||[]).includes(value);
    if(key==='mitre')return (e.mitre||[]).includes(value);
    return String(e[key]??'')===String(value);
  }));
}
window.labWorkspaceLocalAPI=async function(path,opts={},data){
  const [endpoint,query]=path.split('?'),p=opts.body?JSON.parse(opts.body):{},params=new URLSearchParams(query||'');
  const events=data.events||[],cases=data.cases||[],rules=data.rules||[],synthetic=data.synthetic===true;
  const filters=p.filters||Object.fromEntries([...params].filter(([k])=>!['offset','limit'].includes(k)));
  const rows=filterLocal(events,filters),count=key=>Object.fromEntries(Object.entries(rows.reduce((out,e)=>{const value=e[key]??'unknown';out[value]=(out[value]||0)+1;return out;},{})));
  const summaries=()=>({events:events.length,alerts:cases.length,batches:events.length?1:0,cases:Object.fromEntries(['new','investigating','resolved','false_positive'].map(s=>[s,cases.filter(c=>c.status===s).length])),sources:events.reduce((a,e)=>(a[e.source]=(a[e.source]||0)+1,a),{}),recent:events.length?[{created_at:data.created_at||new Date().toISOString(),risk:data.risk||'unknown',event_count:events.length,alert_count:cases.length}]:[]});
  const readonly=new Set(['workspace/query','workspace/analytics','workspace/copilot','workspace/rules/test']);
  if(opts.method&&opts.method!=='GET'&&!readonly.has(endpoint))throw new Error('Bu işlem özel SOC bağlantısı gerektirir. Sekme analizi sunucuya kaydedilmez.');
  if(endpoint==='summary')return summaries();
  if(endpoint==='rules')return {rules};
  if(endpoint==='watchlist'||endpoint==='audit')return {items:[]};
  if(endpoint==='events'||endpoint==='workspace/query'){
    const offset=Number(p.offset||params.get('offset')||0),limit=Number(p.limit||params.get('limit')||100);
    return {items:rows.slice(offset,offset+limit),total:rows.length,offset,limit,has_more:offset+limit<rows.length};
  }
  if(endpoint==='cases'||endpoint==='workspace/cases')return {items:cases.filter(c=>!params.get('status')||c.status===params.get('status'))};
  if(endpoint==='intelligence')return {total:events.length,missing_time:events.filter(e=>!e.timestamp).length,missing_ip:events.filter(e=>!e.ip).length,unparsed:events.filter(e=>e.source==='unknown').length,severities:cases.reduce((a,c)=>(a[c.severity]=(a[c.severity]||0)+1,a),{}),timeline:[],ips:[...new Set(events.map(e=>e.ip).filter(Boolean))].map(ip=>({ip,scope:'unknown',events:events.filter(e=>e.ip===ip).length,alerts:cases.filter(c=>c.ip===ip).length,reputation:'unknown'}))};
  if(endpoint==='source-health')return {items:Object.keys(summaries().sources).map(source=>({source,events:events.filter(e=>e.source===source).length,missing_time:events.filter(e=>e.source===source&&!e.timestamp).length,missing_ip:events.filter(e=>e.source===source&&!e.ip).length,last_event:events.filter(e=>e.source===source&&e.timestamp).map(e=>e.timestamp).sort().at(-1),last_ingested:null})),heartbeat_available:false};
  if(endpoint==='workspace/capabilities')return {version:'7.0',principal:{name:synthetic?'demo':'local-analysis',role:'reader'},cloud_write:false,persistence:'Browser memory only',limits:{query_records:500}};
  if(endpoint==='workspace/analytics'){
    const hours={};for(const e of rows)if(e.timestamp)hours[e.timestamp.slice(0,13)]=(hours[e.timestamp.slice(0,13)]||0)+1;
    return {counts:{total:rows.length,failures:rows.filter(e=>e.outcome==='failure').length,missing_time:rows.filter(e=>!e.timestamp).length},timeline:Object.entries(hours).sort().map(([hour,events])=>({hour,events})),sources:Object.entries(count('source')).map(([source,events])=>({source,events})),severities:Object.entries(count('severity')).map(([severity,events])=>({severity,events})),state:rows.length?'ready':'no_matching_data',entities:Object.fromEntries(['ip','host','user'].map(key=>[key,Object.entries(count(key)).filter(([v])=>v!=='unknown').sort((a,b)=>b[1]-a[1]).slice(0,10).map(([entity,events])=>({entity,events}))]))};
  }
  if(endpoint==='workspace/search'||endpoint==='search')return {events:rows.slice(0,50),event_total:rows.length,cases:cases.filter(c=>JSON.stringify(c).includes(params.get('q')||'')),rules:[]};
  if(endpoint==='workspace/sources')return {sources:Object.keys(summaries().sources).map(id=>({id,kind:id,last_ingested:null})),collectors:[],quality:{events:events.length,missing_time:events.filter(e=>!e.timestamp).length,unparsed:events.filter(e=>e.source==='unknown').length}};
  if(['workspace/investigations','workspace/saved-queries','workspace/query-history','workspace/aliases'].includes(endpoint))return {items:[]};
  if(endpoint==='workspace/custody')return {items:[],verification:{verified:null,scope:'Local browser analysis has no server custody ledger'}};
  if(endpoint==='workspace/sync')return {configured:false,pending:0,sent:0,failed:0};
  if(endpoint==='workspace/rules')return {builtin:rules,custom:[],reviews:[]};
  if(endpoint==='workspace/copilot'){
    let selected=rows;
    const duration=(p.question||'').match(/(?:son|last)\s+(\d{1,3})\s*(dakika|minutes?|dk|saat|hours?|gün|days?)/i);
    if(duration){const unit=duration[2].toLowerCase(),minutes=Number(duration[1])*(/^(saat|hour)/.test(unit)?60:/^(gün|day)/.test(unit)?1440:1);if(minutes>43200||minutes<1)throw new Error('Araştırma aralığı sınırı aşıldı.');filters.start=new Date(Date.now()-minutes*60000).toISOString();filters.end=new Date().toISOString();selected=filterLocal(events,filters);}
    if(p.context?.case_id){const c=cases.find(c=>String(c.id)===String(p.context.case_id));const ids=new Set(JSON.parse(c?.evidence_json||'[]'));selected=selected.filter(e=>ids.has(e.event_id));}
    if(/başarısız|failed|failure|brute/i.test(p.question))selected=selected.filter(e=>e.outcome==='failure');
    const ip=(p.question||'').match(/\b(?:\d{1,3}\.){3}\d{1,3}\b/);if(ip)selected=selected.filter(e=>e.ip===ip[0]);
    const top={};for(const e of selected)if(e.ip)top[e.ip]=(top[e.ip]||0)+1;
    return {answer:p.language==='en'?selected.length+' matching events.':selected.length+' olay eşleşti.',assessment:p.language==='en'?'Verify original evidence; this is not a verdict of compromise.':'Kaynak kanıtını doğrulayın; bu çıktı kesin saldırı kararı değildir.',evidence:selected.slice(0,20),counts:{matched:selected.length,reviewed:Math.min(200,selected.length),top_ips:Object.entries(top).sort((a,b)=>b[1]-a[1]).map(([ip,count])=>({ip,count}))},read_only:true,ai_generated:false,insufficient_data:!selected.length,filters,tools:[{tool:'search_events',source:synthetic?'synthetic_demo':'local_browser_analysis'}],limitations:['Yalnızca bu sekmeye yüklenen kayıtlar incelendi.']};
  }
  if(endpoint==='workspace/rules/test'){
    const rule=p.rule,selection=rule?.detection?.selection;if(!selection||rule.detection.condition!=='selection')throw new Error('Yalnızca tek selection koşulu desteklenir.');
    const matches=rows.filter(e=>Object.entries(selection).every(([key,expected])=>{const [field,modifier]=key.split('|');if(modifier&&!['contains','endswith'].includes(modifier))throw new Error('Desteklenmeyen değiştirici');let value=e[field];if(field==='EventID'){try{value=JSON.parse(e.raw).EventID;}catch{return false;}}const v=String(value??'').toLowerCase();return (Array.isArray(expected)?expected:[expected]).some(x=>modifier==='contains'?v.includes(String(x).toLowerCase()):modifier==='endswith'?v.endsWith(String(x).toLowerCase()):v===String(x).toLowerCase());}));
    return {reviewed:rows.length,alerts:matches.map(e=>({reason:rule.title,event_ids:[e.event_id]})).slice(0,100),persisted:false};
  }
  if(endpoint==='platform/report')return {totals:{events:events.length,batches:events.length?1:0},cases,limitations:['Current browser analysis only; no server custody ledger.'],ai_generated:false};
  if(endpoint.startsWith('workspace/evidence/')){const e=events.find(e=>e.event_id===endpoint.slice(19));if(!e)throw new Error('Olay bulunamadı.');return {event:e,cases:cases.filter(c=>JSON.parse(c.evidence_json||'[]').includes(e.event_id)),occurrences:[],batch:null};}
  const timeline=endpoint.match(/^cases\/(\d+)\/timeline$/);if(timeline){const c=cases.find(c=>c.id===Number(timeline[1]));return {items:events.filter(e=>JSON.parse(c?.evidence_json||'[]').includes(e.event_id))};}
  const explain=endpoint.match(/^cases\/(\d+)\/explain$/);if(explain){const c=cases.find(c=>c.id===Number(explain[1]));return {headline:c?.rule_id,summary:c?.reason,ai_generated:false};}
  if(endpoint.startsWith('platform/modules/')){const group={network:['suricata','zeek','firewall'],endpoint:['windows','sysmon','wazuh'],ad:['windows'],web:['web'],dns:['dns'],cloud:['cloudtrail','cloudflare'],honeypot:['cowrie'],forensics:events.map(e=>e.source)}[endpoint.split('/').at(-1)]||[];return {items:events.filter(e=>group.includes(e.source)).slice(0,200),count:events.filter(e=>group.includes(e.source)).length,scope:'current_browser_analysis'};}
  if(endpoint==='platform/integrations')return {items:['grafana','loki','gns3','wazuh'].map(service=>({service,state:'not_configured'}))};
  if(endpoint==='platform/ueba')return {items:[],state:'insufficient_baseline'};
  throw new Error('Bu özellik özel API ve bağlı servis gerektirir.');
};

