  function bars(target,rows,label,value){target.replaceChildren();if(!rows.length){target.append(el('p','muted','Bu kapsamda veri yok.'));return;}const max=Math.max(1,...rows.map(r=>Number(r[value])||0));for(const row of rows){const line=el('div','v7-bar-row'),track=el('div','v7-bar'),fill=el('i');fill.style.width=(100*Number(row[value])/max)+'%';track.append(fill);line.append(el('span','',row[label]||'Bilinmiyor'),track,el('strong','',row[value]));target.append(line);}}
  function timeline(target,rows){target.replaceChildren();if(!rows.length){target.append(el('p','muted','Zaman bilgisi bulunan kayıt yok.'));return;}const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 720 180');svg.setAttribute('role','img');svg.setAttribute('aria-label','Olay hacmi zaman çizelgesi');const max=Math.max(1,...rows.map(r=>r.events)),points=rows.map((r,i)=>[20+i/Math.max(1,rows.length-1)*680,150-Number(r.events)/max*120]);const polygon=document.createElementNS(ns,'polygon');polygon.setAttribute('points',[[20,150],...points,[700,150]].map(p=>p.join(',')).join(' '));polygon.setAttribute('fill','#1cd4bb20');svg.append(polygon);const path=document.createElementNS(ns,'polyline');path.setAttribute('points',points.map(p=>p.join(',')).join(' '));path.setAttribute('fill','none');path.setAttribute('stroke','#1cd4bb');path.setAttribute('stroke-width','3');svg.append(path);for(let i=0;i<points.length;i++){const c=document.createElementNS(ns,'circle');c.setAttribute('cx',String(points[i][0]));c.setAttribute('cy',String(points[i][1]));c.setAttribute('r','4');c.setAttribute('fill','#93ffeb');const title=document.createElementNS(ns,'title');title.textContent=rows[i].hour+' · '+rows[i].events;c.append(title);svg.append(c);}target.append(svg,el('small','muted',rows[0].hour+' → '+rows.at(-1).hour+' UTC'));}
  async function inspect(event){returnFocus=root.activeElement||document.activeElement;setSelected(event);drawer.hidden=false;$('#v7EvidenceRaw').textContent=event.raw||'';$('#v7EvidenceFields').textContent=JSON.stringify(event,null,2);const meta=$('#v7EvidenceMeta');meta.replaceChildren();for(const [key,value]of Object.entries({event_id:event.event_id,source:event.source,timestamp:event.timestamp,host:event.host,user:event.user,ip:event.ip,severity:event.severity||'Kural eşleşmesi yok'})){const row=el('div','v7-field');row.append(el('span','',key),el('code','',value??'Bilinmiyor'));meta.append(row);}$('#v7EvidenceLinks').replaceChildren();drawer.querySelector('h2').focus();if(state.mode==='private'){try{const data=await api('workspace/evidence/'+encodeURIComponent(event.event_id));if(state.selected?.event_id!==event.event_id)return;const links=$('#v7EvidenceLinks');if(data.batch){links.append(el('h3','','Kaynak paket'),el('code','v7-hash',data.batch.sha256));$('#v7Batch').value=String(data.event.batch_id);}for(const c of data.cases||[]){const b=el('button','smallbutton','#'+c.id+' · '+c.rule_id);b.addEventListener('click',()=>{selectCase(c).catch(e=>message(e.message,true));openSection('cases-section',true);});links.append(b);}}catch(error){$('#v7EvidenceLinks').append(el('p','muted',event.provenance==='loki'?'Bu kayıt şu an yalnızca Loki kaynağında. SOC’a içe alındığında vaka/manifesto ile ilişkilendirilir.':error.message));}}}
