  async function loadRules(){const data=await api('workspace/rules'),list=$('#v7RuleLibrary');list.replaceChildren();for(const rule of data.builtin||[]){const item=el('article','v7-rule');item.append(el('span','tag',rule.id+' · '+rule.severity),el('strong','',rule.name),el('small','',rule.mitre||'MITRE eşlemesi yok'));list.append(item);}for(const item of data.custom||[]){const b=el('button','v7-rule',item.id+' · v'+item.version+' · '+(item.active?'Etkin':'Taslak'));b.addEventListener('click',async()=>{$('#v7RuleEditor').value=JSON.stringify(item.rule,null,2);$('#v7ActivateRule').checked=Boolean(item.active);const data=await api('workspace/rules/'+encodeURIComponent(item.id)+'/versions');const versions=$('#v7RuleVersions');versions.replaceChildren(el('h4','','Sürüm geçmişi'));for(const v of data.items)versions.append(el('p','','v'+v.version+' · '+v.actor+' · '+v.at));});list.append(b);}for(const row of data.reviews||[])list.append(el('small','disclaimer',row.rule_id+' · '+row.cases+' vaka · '+row.reviewed_false_positives+' yanlış pozitif etiketi'));}
