  async function loadAliases(){const data=await api('workspace/aliases');const box=$('#v7Aliases');box.replaceChildren();for(const a of data.items){const b=el('button','v7-record',a.value+' → '+a.alias);b.addEventListener('click',()=>{setContext({host:a.alias});explore(state.filters);});box.append(b);}return data.items;}
