  action('v7Agents',async()=>{status('#v7AgentState','Wazuh sorgulanıyor…','loading');try{const data=await api('platform/wazuh/agents');const agents=data.result?.data?.affected_items||[],list=$('#v7AgentList');list.replaceChildren();for(const agent of agents){const b=el('button','v7-agent');b.append(el('strong','',agent.name||agent.id),el('span','',agent.status||'unknown'),el('small','',agent.lastKeepAlive||'Son temas bilinmiyor'));b.addEventListener('click',async()=>{setContext({host:agent.name});const data=await json('workspace/query',{filters:state.filters,limit:100});recordButtons($('#v7EndpointEvents'),data.items);});list.append(b);}status('#v7AgentState',agents.length+' ajan · Durum Wazuh raporudur; veri eksiksizliği garantisi değildir.','ready');}catch(error){status('#v7AgentState','Wazuh çevrimdışı veya yapılandırılmadı: '+error.message,'error');throw error;}});
