  action('v7ExportSelected',()=>download({events:[...state.selection.values()],filters:state.filters,mode:state.mode,exported_at:new Date().toISOString()},'selected-evidence.json'));action('v7ClearSelection',()=>{state.selection.clear();augmentEvents(state.events);});
  function augmentEvents(items){state.events=items;const table=$('#eventsBody').closest('table'),head=table.querySelector('thead tr');if(!head.querySelector('[data-v7-select]')){const th=el('th');th.dataset.v7Select='true';th.textContent='SEÇ';head.prepend(th);for(const label of ['HOST','KULLANICI','SEVİYE'])head.append(el('th','',label));for(const [i,key]of [[1,'timestamp'],[2,'source'],[3,'ip'],[4,'action'],[5,'outcome']]){const button=el('button','v7-sort',head.children[i].textContent+' ↕');head.children[i].replaceChildren(button);let ascending=true;button.addEventListener('click',()=>{ascending=!ascending;const sorted=[...state.events].sort((a,b)=>String(a[key]||'').localeCompare(String(b[key]||''))*(ascending?1:-1));const body=$('#eventsBody');const rows=new Map([...body.rows].map(r=>[r.dataset.eventId,r]));for(const e of sorted)if(rows.has(e.event_id))body.append(rows.get(e.event_id));head.children[i].setAttribute('aria-sort',ascending?'ascending':'descending');});}}const rows=[...$('#eventsBody').rows];items.forEach((event,index)=>{const row=rows[index];if(!row)return;row.dataset.eventId=event.event_id;row.querySelectorAll('[data-v7-cell]').forEach(e=>e.remove());const cell=el('td');cell.dataset.v7Cell='true';const check=el('input');check.type='checkbox';check.checked=state.selection.has(event.event_id);check.setAttribute('aria-label','Olayı seç '+event.event_id);check.addEventListener('change',()=>{if(check.checked&&state.selection.size<100)state.selection.set(event.event_id,event);else{state.selection.delete(event.event_id);check.checked=false;}$('#v7SelectedCount').textContent=state.selection.size+' seçili';});cell.append(check);row.prepend(cell);for(const value of [event.host||'—',event.user||'—',event.severity||'Kural eşleşmesi yok']){const c=el('td','',value);c.dataset.v7Cell='true';row.append(c);}});$('#v7SelectedCount').textContent=state.selection.size+' seçili';}
  async function syncStatus(){const s=await api('workspace/sync');status('#v7SyncState',s.configured?`${s.pending} bekleyen paket · ${s.sent} iletildi · ${s.failed} tekrar denenecek`:'Buluta yükleme için sunucuda ayrı yazma yetkisi gerekli. SOC analizi çalışmaya devam eder.',s.failed?'error':'ready');return s;}
