  $('#v7GlobalForm').addEventListener('submit',async e=>{e.preventDefault();const q=$('#v7GlobalSearch').value.trim();if(!q)return;const box=$('#v7GlobalResults');box.hidden=false;box.replaceChildren(el('p','','Aranıyor…'));try{const data=await api('workspace/search?'+new URLSearchParams({q}));box.replaceChildren(el('h3','',data.event_total+' olay eşleşti'));const records=el('div','v7-records');recordButtons(records,data.events);box.append(records);for(const c of data.cases||[]){const b=el('button','smallbutton','#'+c.id+' · '+c.rule_id);b.addEventListener('click',()=>{selectCase(c).catch(e=>message(e.message,true));openSection('cases-section',true);});box.append(b);}for(const rule of data.rules||[])box.append(el('p','',rule.id+' · '+rule.name));const close=el('button','smallbutton','Aramayı kapat');close.addEventListener('click',()=>box.hidden=true);box.append(close);}catch(error){box.replaceChildren(el('p','message error',error.message));}});
