  const stopLive=()=>{state.stream?.abort();state.stream=null;clearTimeout(reconnectTimer);status('#v7LiveState','Durduruldu');};
  async function connectLive(){if(!state.stream)return;if(document.hidden){reconnectTimer=setTimeout(connectLive,5000);return;}const controller=state.stream;try{const response=await openStream(state.cursor,controller.signal);if(!response||!response.ok)throw new Error('Akış için özel API bağlantısı gerekli.');status('#v7LiveState','Bağlı · SSE');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(!controller.signal.aborted){const {value,done}=await reader.read();if(done||controller.signal.aborted||state.stream!==controller)break;buffer+=decoder.decode(value,{stream:true});let index;while((index=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,index);buffer=buffer.slice(index+2);const line=block.split('\n').find(l=>l.startsWith('data: '));if(!line)continue;const data=JSON.parse(line.slice(6));state.cursor=data.cursor||state.cursor;liveItems=[...data.items,...liveItems].slice(0,200);recordButtons($('#v7LiveEvents'),liveItems);}}if(!controller.signal.aborted){status('#v7LiveState','Yeniden bağlanıyor…');reconnectTimer=setTimeout(connectLive,1000);}}catch(error){if(!controller.signal.aborted){status('#v7LiveState','Bağlantı yok; 10 saniye sonra yeniden denenecek.','error');reconnectTimer=setTimeout(connectLive,10000);}}}
  action('v7StartLive',()=>{stopLive();if(state.mode!=='private'){recordButtons($('#v7LiveEvents'),filterLocal(state.events,state.filters));status('#v7LiveState','Sekme / örnek görünüm · Canlı sunucu akışı değildir.');return;}state.stream=new AbortController();connectLive();});action('v7StopLive',stopLive);
  function reset(){state.revision++;stopLive();state.filters={};state.selected=null;state.caseId=null;state.selection.clear();state.events=[];state.cursor=0;state.mode='disconnected';state.capabilities=null;manifest=null;activeInvestigation=null;chartItems=[];liveItems=[];closeDrawer();for(const id of ['v7EvidenceRaw','v7EvidenceFields','v7EvidenceMeta','v7EvidenceLinks','v7Printable'])$('#'+id).replaceChildren();for(const id of ['v7InvestigationTitle','v7InvestigationNotes','v7QueryName','v7CaseTitle','v7Question','v7GlobalSearch','v7Assignee','v7AliasValue','v7AliasHost'])$('#'+id).value='';$('#v7UseModel').checked=false;$('#v7SyncOnIngest').checked=false;for(const id of ['v7ChartLogs','v7ChartMetrics','v7ChartTimeline','v7ChartSources','v7CopilotResult','v7GlobalResults','v7InvestigationList','v7SavedQueries','v7QueryHistory','v7RuleLibrary','v7RuleTestResult','v7RuleVersions','v7Manifest','v7Custody','v7TopologyCanvas','v7Aliases','v7AgentList','v7EndpointEvents','v7LiveEvents','v7Assignments','v7OverviewTimeline','v7TopEntities','v7CollectorHealth'])$('#'+id).replaceChildren();$('#v7GlobalResults').hidden=true;tokens();writeControls();}
  async function ready(mode){state.mode=mode;state.capabilities=await api('workspace/capabilities');$('#v7Mode').textContent=mode==='private'?'PRIVATE SOC':mode==='demo'?'SENTETİK DEMO':'SEKME ANALİZİ';$('#v7UseModel').disabled=mode!=='private';$('#v7ChartSource option[value="loki"]').disabled=mode!=='private';$('#v7CopilotSource option[value="loki"]').disabled=mode!=='private';if(mode!=='private'){$('#v7ChartSource').value='soc';$('#v7CopilotSource').value='soc';}tokens();writeControls();await overviewRefresh();await syncStatus();}
  const onSection=id=>{root.querySelector('.sidebar').classList.remove('v7-menu-open');$('#v7Menu').setAttribute('aria-expanded','false');if(state.mode==='disconnected')return;const loaders={'grafana-view':renderCharts,'investigations':loadInvestigations,'detection-studio':loadRules,'evidence-center':loadCustody,'cases-section':loadAssignments};if(loaders[id])loaders[id]().catch(error=>message(error.message,true));};
  const clock=()=>{if(!document.hidden)$('#v7Clock').textContent=new Date().toISOString().slice(0,19).replace('T',' ')+' UTC';};clock();setInterval(clock,30000);
  tokens();writeControls();
  return {ready,reset,onSection,inspect,selectCase,applyPermissions:writeControls,eventPage(items,filters){augmentEvents(items);if(filters)setContext(filters,{replace:true});},get filters(){return {...state.filters};},get selected(){return state.selected;},ingestOptions(){return {sync_loki:$('#v7SyncOnIngest').checked,source_id:$('#v7SourceId').value.trim()||'site-upload'};},async afterIngest(result){$('#v7Batch').value=String(result.batch_id);await syncStatus();},setContext};
